import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import { FaCalendarPlus, FaMagic, FaList, FaClock } from "react-icons/fa";
import AlertBox from "./AlertBox";
import DashboardCard from "./DashboardCard";
import PageHeader from "./PageHeader";
import SectionCard from "./SectionCard";
import "./dashboard.css";

function Planner() {
  const userId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [plans, setPlans] = useState([]);
  const [alert, setAlert] = useState(null);

  const [manualForm, setManualForm] = useState({
    course_id: "",
    study_date: "",
    topic: ""
  });

  const [autoForm, setAutoForm] = useState({
    course_id: "",
    start_date: "",
    topics: ""
  });

  const fetchData = useCallback(async () => {
    try {
      const coursesRes = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = coursesRes.data.courses || [];

      const enrollRes = await axios.get(
        `http://127.0.0.1:8000/enrollments/${userId}`
      );

      const enrolledIds = enrollRes.data.map((e) => e.course_id);
      const myCourses = allCourses.filter((c) => enrolledIds.includes(c.id));
      setCourses(myCourses);

      const plansRes = await axios.get(
        `http://127.0.0.1:8000/planner/${userId}`
      );
      setPlans(plansRes.data.plans || []);
    } catch (error) {
      console.error(error);
    }
  }, [userId]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleManualChange = (e) => {
    setManualForm({
      ...manualForm,
      [e.target.name]: e.target.value
    });
  };

  const handleAutoChange = (e) => {
    setAutoForm({
      ...autoForm,
      [e.target.name]: e.target.value
    });
  };

  const handleManualSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        user_id: parseInt(userId),
        course_id: parseInt(manualForm.course_id),
        study_date: manualForm.study_date,
        topic: manualForm.topic
      };

      const response = await axios.post(
        "http://127.0.0.1:8000/create-plan",
        payload
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      setManualForm({
        course_id: "",
        study_date: "",
        topic: ""
      });

      fetchData();
      window.dispatchEvent(new Event("plannerUpdated"));
    } catch (error) {
      console.error(error);
      setAlert({
        message: "Failed to create manual plan",
        type: "error"
      });
    }
  };

  const handleAutoSubmit = async (e) => {
    e.preventDefault();

    try {
      const topicsArray = autoForm.topics
        .split(",")
        .map((item) => item.trim())
        .filter((item) => item !== "");

      const payload = {
        user_id: parseInt(userId),
        course_id: parseInt(autoForm.course_id),
        start_date: autoForm.start_date,
        topics: topicsArray
      };

      const response = await axios.post(
        "http://127.0.0.1:8000/auto-plan",
        payload
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      setAutoForm({
        course_id: "",
        start_date: "",
        topics: ""
      });

      fetchData();
      window.dispatchEvent(new Event("plannerUpdated"));
    } catch (error) {
      console.error(error);
      setAlert({
        message: "Failed to create auto plan",
        type: "error"
      });
    }
  };

  const totalPlans = plans.length;
  const totalCourses = courses.length;
  const today = new Date().toISOString().split("T")[0];
  const todaysPlans = plans.filter((p) => p.study_date === today).length;

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <PageHeader
        title="Study Planner"
        subtitle="Plan your study manually or generate an auto schedule from topics."
      />

      <div className="grid-4" style={{ marginBottom: "18px" }}>
        <DashboardCard
          icon={<FaList />}
          label="Total Plans"
          value={totalPlans}
        />
        <DashboardCard
          icon={<FaCalendarPlus />}
          label="Today's Plans"
          value={todaysPlans}
        />
        <DashboardCard
          icon={<FaMagic />}
          label="Enrolled Courses"
          value={totalCourses}
        />
        <DashboardCard
          icon={<FaClock />}
          label="Planner Status"
          value="Ready"
          badge="Smart"
        />
      </div>

      <div className="grid-2" style={{ marginBottom: "18px" }}>
        <SectionCard title="Manual Plan">
          <form onSubmit={handleManualSubmit}>
            <select
              className="select"
              name="course_id"
              value={manualForm.course_id}
              onChange={handleManualChange}
            >
              <option value="">Select Course</option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title}
                </option>
              ))}
            </select>

            <input
              className="input"
              type="date"
              name="study_date"
              value={manualForm.study_date}
              onChange={handleManualChange}
            />

            <input
              className="input"
              type="text"
              name="topic"
              placeholder="Topic"
              value={manualForm.topic}
              onChange={handleManualChange}
            />

            <button className="btn btn-primary" type="submit">
              Create Plan
            </button>
          </form>
        </SectionCard>

        <SectionCard title="Auto Plan Generator">
          <form onSubmit={handleAutoSubmit}>
            <select
              className="select"
              name="course_id"
              value={autoForm.course_id}
              onChange={handleAutoChange}
            >
              <option value="">Select Course</option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title}
                </option>
              ))}
            </select>

            <input
              className="input"
              type="date"
              name="start_date"
              value={autoForm.start_date}
              onChange={handleAutoChange}
            />

            <textarea
              className="textarea"
              name="topics"
              placeholder="Enter topics separated by comma"
              value={autoForm.topics}
              onChange={handleAutoChange}
            />

            <button className="btn btn-primary" type="submit">
              Generate Auto Plan
            </button>
          </form>
        </SectionCard>
      </div>

      <SectionCard title="My Study Plans">
        {plans.length === 0 ? (
          <p>No plans found.</p>
        ) : (
          <div className="table-wrap">
            <table className="table">
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Topic</th>
                  <th>Course ID</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {plans.map((plan) => (
                  <tr key={plan.id}>
                    <td>{plan.study_date}</td>
                    <td>{plan.topic}</td>
                    <td>{plan.course_id}</td>
                    <td>
                      <span className="badge badge-purple">Planned</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </SectionCard>
    </div>
  );
}

export default Planner;
